// needed for the next test requests
const responseData = pm.response.json();
const jwtToken = responseData.token;
pm.collectionVariables.set("jwtToken", jwtToken);

pm.test("User registered successfully", () => {
    pm.expect(responseData.message).to.eql("User registered successfully");    
});

pm.test("User registration result returns proper user JSON", () => {
    pm.expect(responseData.user.id).to.be.a("number");
    pm.expect(responseData.user.email).to.be.a("string");
    pm.expect(responseData.user.username).to.be.a("string");
    pm.expect(responseData.user.createdat).to.be.a("string");
});

pm.test("Successful user registration result returns user's JWT token", () => {
    pm.expect(responseData.token).to.be.a("string");
});

const timestamp = Date.now();
const jsonPayload = {
    username: `user${timestamp}`,
    email: `user${timestamp}@gmail.com`,
    password: `password${timestamp}`
};

pm.request.body.raw = JSON.stringify(jsonPayload);

pm.collectionVariables.set("registeredUsername", jsonPayload.username);
pm.collectionVariables.set("registeredEmail", jsonPayload.email);
pm.collectionVariables.set("registeredPassword", jsonPayload.password);

const token = pm.collectionVariables.get("jwtToken");

pm.request.headers.upsert({
    key: "Authorization",
    value: "Bearer " + token
});

const responseData = pm.response.json();

pm.test("User account info is returned with correct data types", () => {
    pm.expect(responseData.user.id).to.be.a("number");
    pm.expect(responseData.user.email).to.be.a("string");
    pm.expect(responseData.user.username).to.be.a("string");
    pm.expect(responseData.user.role).to.be.a("string");
    pm.expect(responseData.user.created_at).to.be.a("string");
});

const jsonPayload = {
    username: "admin",
    email: "admin@jucsef.me",
    password: "admin123"
};

pm.request.body.raw = JSON.stringify(jsonPayload);

const responseData = pm.response.json();

pm.test("User can successfully log in", () => {
    pm.response.to.have.status(200);
    pm.expect(responseData.message).to.be.a("string");
    pm.expect(responseData.message).to.equal("Login successful");
});

pm.test("User's account ID and username is returned on successful log in", () => {
    pm.expect(responseData.user.id).to.be.a("number");
    pm.expect(responseData.user.username).to.be.a("string");
});

pm.test("User's JWT token is returned on successful log in", () => {
    pm.expect(responseData.token).to.be.a("string");
});

// store for role update endpoint test
pm.collectionVariables.set("adminJwtToken", responseData.token);

const token = pm.collectionVariables.get("adminJwtToken");

pm.request.headers.upsert({
    key: "Authorization",
    value: "Bearer " + token
});

const jsonPayload = {
    username: pm.collectionVariables.get("registeredUsername"),
    role: "ADMIN"
};
pm.request.body.raw = JSON.stringify(jsonPayload);

const responseData = pm.response.json();

pm.test("Admin user can successfully update user role", () => {
    pm.response.to.have.status(200);
    pm.expect(responseData.username).to.be.a("string");
    pm.expect(responseData.role).to.be.a("string");
});
